import React, { useEffect, useState, useContext } from 'react';
import axios from 'axios';
import ExerciseCard from '../components/ExerciseCard';
import { Web3Context } from '../contexts/Web3Context';

const Marketplace = () => {
  const [exercises, setExercises] = useState([]);
  const { currentAccount } = useContext(Web3Context);

  useEffect(() => {
    const fetchExercises = async () => {
      try {
        const res = await axios.get('http://localhost:5000/api/exercises');
        setExercises(res.data);
      } catch (err) {
        console.error(err);
      }
    };
    fetchExercises();
  }, []);

  return (
    <div className="py-10 animate-fade-in-up">
      <div className="text-center mb-12">
        <h1 className="text-5xl font-extrabold text-white drop-shadow-md mb-4">
          Marketplace
        </h1>
        <p className="text-white text-lg opacity-90">
          Thử thách bản thân, kiếm Token thật từ kiến thức của bạn.
        </p>
      </div>
      
      {!currentAccount && (
        <div className="glass-panel p-4 mb-8 text-center text-red-500 font-bold max-w-lg mx-auto">
          ⚠️ Vui lòng kết nối ví để tham gia!
        </div>
      )}

      {/* Grid Layout sử dụng CSS Grid mới */}
      <div className="grid-layout">
        {exercises.length === 0 ? (
          <div className="col-span-full text-center text-white text-xl mt-10">
            Đang tải dữ liệu hoặc chưa có bài tập nào...
          </div>
        ) : (
          exercises.map(ex => (
            <div className="transform hover:-translate-y-2 transition duration-300" key={ex._id}>
               <ExerciseCard exercise={ex} />
            </div>
          ))
        )}
      </div>
    </div>
  );
};

export default Marketplace;
